import java.util.*;

public class Main {
    static long solveOne(int n, long x, int[] arr) {
        int mn = arr[0];
        int maxA = arr[0];

        for (int v : arr) {
            mn = Math.min(mn, v);
            maxA = Math.max(maxA, v);
        }

        // 如果初始值已经小于最小模数，所有取模都不会改变结果
        if (x < mn) {
            return x;
        }

        // 去重，减少枚举次数
        boolean[] exist = new boolean[maxA + 1];
        ArrayList<Integer> nums = new ArrayList<>();
        for (int v : arr) {
            if (!exist[v]) {
                exist[v] = true;
                nums.add(v);
            }
        }

        boolean[] vis = new boolean[maxA + 1];
        Queue<Integer> q = new LinkedList<>();

        // 第一次取模得到初始状态
        for (int a : nums) {
            if (a <= x) {
                int r = (int)(x % a);
                if (!vis[r]) {
                    vis[r] = true;
                    q.offer(r);
                }
            }
        }

        // BFS 枚举所有可达状态
        while (!q.isEmpty()) {
            int v = q.poll();

            for (int a : nums) {
                // 只有 a <= v 时，取模才会改变当前值
                if (a <= v) {
                    int nv = v % a;
                    if (!vis[nv]) {
                        vis[nv] = true;
                        q.offer(nv);
                    }
                }
            }
        }

        int ans = 0;
        for (int i = 0; i < mn; i++) {
            if (vis[i]) {
                ans = i;
            }
        }

        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int T = sc.nextInt();
        StringBuilder sb = new StringBuilder();

        for (int tc = 0; tc < T; tc++) {
            int n = sc.nextInt();
            long x = sc.nextLong();

            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = sc.nextInt();
            }

            sb.append(solveOne(n, x, arr)).append('\n');
        }

        System.out.print(sb.toString());
        sc.close();
    }
}
```

